import { ok, fail } from './result.js';
import { formatEuros, roundCents } from './money.js';
import { getCustomer } from './customers.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ ok: true, value: string } | { ok: false, error: string }}
 */
export function renderInvoiceText(invoice) {
  if (!invoice || !invoice.customerId) {
    return fail('INVALID_INVOICE');
  }

  // Look up customer
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;

  // Calculate totals
  const totalsResult = invoiceTotals(invoice);
  if (!totalsResult.ok) return totalsResult;
  const { subtotal, discount, total } = totalsResult.value;

  const customer = customerResult.value;
  const lines = [];

  // First line: invoice number or DRAFT
  lines.push(invoice.number ?? 'DRAFT');

  // Customer name
  lines.push(customer.name);

  // Invoice lines
  for (const line of invoice.lines) {
    const lineTotal = line.qty * line.unitPrice;
    const lineParts = [
      `${line.qty}x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(lineTotal)}`,
    ];

    // Add discount if present
    if (line.discountPercent > 0) {
      const lineDiscountFractional = lineTotal * line.discountPercent / 100;
      const lineDiscount = roundCents(lineDiscountFractional);
      lineParts.push(`(${line.discountPercent}% off = -${formatEuros(lineDiscount)})`);
    }

    lines.push(lineParts.join(' '));
  }

  // Add subtotal and discount if there's a discount
  if (discount > 0) {
    lines.push(`Subtotal: ${formatEuros(subtotal)}`);
    lines.push(`Discount: -${formatEuros(discount)}`);
  }

  // Add total
  lines.push(`Total: ${formatEuros(total)}`);

  return ok(lines.join('\n'));
}

