  });
  assert.equal(invoiceResult.ok, true);

  const r = renderInvoiceText(invoiceResult.value);
  assert.equal(r.ok, true);
  const text = r.value;

  assert.match(text, /^DRAFT$/m);
  assert.match(text, /^Kite & Co$/m);
  assert.match(text, /5x Development \(hour\)/);
  assert.match(text, /1x Logo package/);
  assert.match(text, /3x Copywriting \(hour\)/);
  assert.match(text, /Subtotal:/);
  assert.match(text, /Discount:/);
  assert.match(text, /Total:/);
});

